"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def splitIntoWords(sentence):
    words = []
    currentWord = ''
    for __reserved_keyword__char in sentence:
        if (__reserved_keyword__char == ' '):
            if (currentWord != ''):
                words.append(currentWord)
            currentWord = ''
        else:
            currentWord = (currentWord + __reserved_keyword__char)
    if (currentWord != ''):
        words.append(currentWord)
    return words
